\r\n        _initialDate: function () {\r\n            if (this.options.currentText) {\r\n                return $.datepicker.parseDate(this._dateFormat, this.options.currentText);\r\n            } else {\r\n                return new Date;\r\n            }\r\n        },\r\n\r\n        _select: function (dateText, inst, onSelect) {\r\n            this._setWeek(this._picker.datepicker('getDate'));\r\n            const startDateText = $.datepicker.formatDate(this._dateFormat, this._startDate, inst.settings);\r\n            this._picker.val(startDateText);\r\n            if (onSelect) {\r\n                onSelect(dateText, startDateText, this._startDate, this._endDate, inst);\r\n            }\r\n        },\r\n\r\n        _showDay: function (date) {\r\n            const cssClass = date >= this._startDate && date <= this._endDate ? 'ui-datepicker-current-day' : '';\r\n            return [true, cssClass];\r\n        },\r\n\r\n        _setWeek: function (date) {\r\n            const selected = moment(date, 'YYYY-MM-DD');\r\n\r\n            const fromDateClone = selected.clone();\r\n            const from_date = fromDateClone.startOf('isoWeek'); // why use isoWeek - https://en.wikipedia.org/wiki/ISO_8601#Week_dates\r\n            this._startDate = from_date.toDate();\r\n\r\n            const toDateClone = selected.clone();\r\n            const to_date = toDateClone.endOf('isoWeek');\r\n            this._endDate = to_date.toDate();\r\n        },\r\n\r\n        _selectCurrentWeek: function () {\r\n            $('.ui-datepicker-calendar').find('.ui-datepicker-current-day a').addClass('ui-state-active');\r\n        },\r\n\r\n        setDate: function (date) {\r\n            this._setWeek(date);\r\n            this._picker.datepicker('setDate', $.datepicker.formatDate(this._dateFormat, date));\r\n            this._picker.hide();\r\n            let onSelect = this.options.onSelect;\r\n            this._select(moment(date).format('DD/MM/YYYY'), this._picker, onSelect);\r\n        }\r\n    });\r\n})(jQuery);","const getChilds = (floatData, data, parentKey, isChecked = false) => {\r\n    const totalItems = data.length;\r\n    for (let i = 0; i < totalItems; i++) {\r\n        const key = parentKey + '-' + i;\r\n\r\n        floatData.push({ ...data[i], checked: isChecked, key: key, parentKey: parentKey });\r\n        data[i] = { ...data[i], checked: isChecked, key: key };\r\n        if (data[i].items && data[i].items.length > 0) {\r\n            getChilds(floatData, data[i].items, key, isChecked);\r\n        }\r\n    }\r\n};\r\n\r\nexport default (data, isChecked = false) => {\r\n    let floatData = [];\r\n    const totalItems = data.length;\r\n    for (let i = 0; i < totalItems; i++) {\r\n        const key = 'item-' + i;\r\n\r\n        floatData.push({ ...data[i], checked: isChecked, key: key, parentKey: '' });\r\n        data[i] = { ...data[i], checked: isChecked, key: key };\r\n        if (data[i].items && data[i].items.length > 0) {\r\n            getChilds(floatData, data[i].items, key, isChecked);\r\n        }\r\n    }\r\n\r\n    return { data, floatData };\r\n};","import React, { Component } from 'react';\r\nimport { Dropdown, MenuItem } from 'react-bootstrap';\r\n\r\nimport Autocomplete from '../../shared/components/Autocomplete';\r\nimport TreeMultiselect from '../../shared/components/react-tree-multiselect/TreeMultiselect';\r\nimport WeekPicker from '../../shared/components/WeekPicker';\r\n\r\nexport default class Search extends Component {\r\n    handleTeamChange = selectedItems => {\r\n        const ids = selectedItems.map(item => item.id);\r\n        this.props.onChange('teamIds', ids.join(','));\r\n    };\r\n\r\n    handleEmployeeChange = value => {\r\n        this.props.onChange('employee', value);\r\n    };\r\n\r\n    handleDateChange = (fromDate, toDate) => {\r\n        this.props.onChange('fromDate', fromDate);\r\n        this.props.onChange('toDate', toDate);\r\n    };\r\n\r\n    handleCategoryChange = e => {\r\n        this.props.onChange('isLocal', e.target.value);\r\n    };\r\n\r\n    handleSubmit = event => {\r\n        this.props.onSubmit(event.target.name === 'currentWeek');\r\n    };\r\n\r\n    render() {\r\n        return (\r\n            <div className=\"filter\">\r\n                <div className=\"form-horizontal clearfix\">\r\n                    <div className=\"form-group form-group--l\">\r\n                        <div className=\"label-form\">\r\n                            <label className=\"control-label\">Week</label>\r\n                        </div>\r\n                        <div className=\"calendar-form\">\r\n                            <WeekPicker\r\n                                fromDate={this.props.filter.fromDate}\r\n                                toDate={this.props.filter.toDate}\r\n                                onChange={this.handleDateChange}\r\n                            />\r\n                        </div>\r\n                    </div>\r\n                    <div className=\"form-group form-group--m\">\r\n                        <div className=\"label-form\">\r\n                            <label className=\"control-label\">Sec./Team</label>\r\n                        </div>\r\n                        <div className=\"select-form\">\r\n                            <TreeMultiselect\r\n                                data={this.props.teamOptions}\r\n                                isSelectedAll\r\n                                onChange={this.handleTeamChange}\r\n                            />\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div className=\"form-group form-group--m\">\r\n                        <div className=\"label-form\">\r\n                            <label className=\"control-label\">Category</label>\r\n                        </div>\r\n                        <div className=\"select-form\">\r\n                            <select className=\"form-control\" value={this.props.filter.isLocal} onChange={this.handleCategoryChange}>\r\n                                <option value >All</option>\r\n                                <option value=\"0\">Expat</option>\r\n                                <option value=\"1\">Local</option>\r\n                            </select>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div className=\"form-group form-group--m\">\r\n                        <div className=\"label-form\">\r\n                            <label className=\"control-label\">Employee</label>\r\n                        </div>\r\n                        <div className=\"select-form\">\r\n                            <Autocomplete\r\n                                className=\"form-control\"\r\n                                sources={this.props.employeeOptions}\r\n                                onInput={this.props.onSearchEmployees}\r\n                                onChange={this.handleEmployeeChange}\r\n                            />\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div className=\"form-horizontal clearfix\">\r\n                    <div className=\"button-group\">\r\n                        <button className=\"btn btn-primary\" onClick={this.handleSubmit}>Submit</button>\r\n                        <button className=\"btn btn-primary\" name=\"currentWeek\" onClick={this.handleSubmit}>\r\n                            Current Week\r\n                        </button>\r\n                        {\r\n                            this.props.showExportExcel &&\r\n                            <Dropdown id={`dropdownExportExcel`} componentClass=\"div\">\r\n                                <Dropdown.Toggle useAnchor className=\"btn btn-excel\">\r\n                                    Excel\r\n                                </Dropdown.Toggle>\r\n                                <Dropdown.Menu>\r\n                                    <MenuItem onClick={this.props.onExportExcel}>Upload</MenuItem>\r\n                                    <MenuItem onClick={this.props.onExportExcelDriverPickup}>Driver Pickup</MenuItem>\r\n                                </Dropdown.Menu>\r\n                            </Dropdown>\r\n                        }\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { Component } from 'react';\r\nimport PropTypes from 'prop-types';\r\n\r\nexport default class Autocomplete extends Component {\r\n    static propTypes = {\r\n        sources: PropTypes.arrayOf(PropTypes.object),\r\n        className: PropTypes.string,\r\n        isDisabled: PropTypes.bool,\r\n        onInput: PropTypes.func,\r\n        onChange: PropTypes.func\r\n    };\r\n\r\n    static defaultProps = {\r\n        sources: [],\r\n        className: '',\r\n        isDisabled: false,\r\n        onInput: function () {\r\n            // This is intentional\r\n        },\r\n        onChange: function () {\r\n            // This is intentional\r\n        }\r\n    };\r\n\r\n    componentDidMount() {\r\n        this.$el = $(this.el);\r\n        this.updateAutocomplete();\r\n    }\r\n\r\n    shouldComponentUpdate(nextProps) {\r\n        return this.props.sources !== nextProps.sources\r\n            || this.props.className !== nextProps.className\r\n            || this.props.isDisabled !== nextProps.isDisabled;\r\n    }\r\n\r\n    componentDidUpdate() {\r\n        this.updateAutocomplete();\r\n    }\r\n\r\n    componentWillUnmount() {\r\n        this.$el.autocomplete('destroy');\r\n    }\r\n\r\n    updateAutocomplete = () => {\r\n        const sources = this.props.sources;\r\n        this.$el.autocomplete({\r\n            source: sources,\r\n            minLength: 2,\r\n            select: (event, ui) => this.handleChange(event, ui),\r\n            change: (event, ui) => this.handleChange(event, ui)\r\n        });\r\n    };\r\n\r\n    handleInput = event => {\r\n        this.props.onInput(event.target.value);\r\n    };\r\n\r\n    handleChange = (event, ui) => {\r\n        let value = 0,\r\n            label = '';\r\n        if (ui && ui.item) {\r\n            label = ui.item.value;\r\n            value = ui.item.id;\r\n        } else {\r\n            if (this.$el.value === '') {\r\n                value = '';\r\n            }\r\n        }\r\n\r\n        this.props.onChange({ value, label });\r\n    };\r\n\r\n    render() {\r\n        return (\r\n            <input\r\n                ref={el => this.el = el}\r\n                type=\"text\"\r\n                className={this.props.className}\r\n                disabled={this.props.isDisabled}\r\n                onInput={this.handleInput}\r\n            />\r\n        );\r\n    }\r\n}","import React from 'react';\r\nimport PropTypes from 'prop-types';\r\n\r\nimport buildData from './buildData';\r\nimport TreeNode from './TreeNode';\r\n\r\nconst updateParent = (floatData, parentKey, isChecked) => {\r\n    const index = floatData.findIndex(item => item.key === parentKey),\r\n        siblings = floatData.filter(item => item.parentKey === parentKey),\r\n        selected = siblings.filter(item => item.checked);\r\n    floatData[index] = { ...floatData[index], checked: siblings.length === selected.length };\r\n\r\n    if (floatData[index].parentKey !== null && floatData[index].parentKey !== '') {\r\n        updateParent(floatData, floatData[index].parentKey, isChecked);\r\n    }\r\n};\r\n\r\nconst updateChild = (floatData, itemkey, isChecked) => {\r\n    const totalItems = floatData.length;\r\n    for (let i = 0; i < totalItems; i++) {\r\n        if (floatData[i].parentKey === itemkey) {\r\n            floatData[i] = { ...floatData[i], checked: isChecked };\r\n            updateChild(floatData, floatData[i].key, isChecked);\r\n        }\r\n    }\r\n};\r\n\r\nconst getSelectedText = (floatData) => {\r\n    const items = floatData.filter(item => item.isLeaf),\r\n        selected = items.filter(item => item.checked);\r\n    let text = '';\r\n\r\n    if (selected.length === 0) {\r\n        text = 'Select options';\r\n    } else if (items.length === selected.length) {\r\n        text = 'All selected';\r\n    } else {\r\n        text = `${selected.length} selected`;\r\n    }\r\n\r\n    return text;\r\n};\r\n\r\nconst getSelectedItems = (floatData) => {\r\n    return floatData.filter(item => item.isLeaf && item.checked);\r\n};\r\n\r\nlet id = 1;\r\n\r\nexport default class TreeMultiselect extends React.Component {\r\n    static propTypes = {\r\n        data: PropTypes.arrayOf(PropTypes.object).isRequired,\r\n        isSelectedAll: PropTypes.bool,\r\n        onChange: PropTypes.func\r\n    }\r\n\r\n    static defaultProps = {\r\n        data: [],\r\n        isSelectedAll: false,\r\n        onChange: function () { }\r\n    }\r\n\r\n    static getDerivedStateFromProps(props, state) {\r\n        if (state.original === props.data) {\r\n            return null;\r\n        }\r\n\r\n        return { ...buildData(props.data || [], props.isSelectedAll), original: props.data };\r\n    }\r\n\r\n    constructor(props) {\r\n        super(props);\r\n        this.id = `multiselect-treeview-${props.id || id++}`;\r\n        this.state = {\r\n            selectedText: 'Select options',\r\n            opened: false\r\n        };\r\n    }\r\n\r\n    componentDidMount() {\r\n        document.addEventListener('click', this.handleDocumentClick);\r\n    }\r\n\r\n    componentWillUnmount() {\r\n        document.removeEventListener('click', this.handleDocumentClick);\r\n    }\r\n\r\n    handleDocumentClick = (event) => {\r\n        const clickOutside = this.wrapper && !this.wrapper.contains(event.target);\r\n        if (clickOutside && this.state.opened) {\r\n            this.setState({ opened: false });\r\n        }\r\n    }\r\n\r\n    onToggle = () => {\r\n        this.setState((prevState) => { return { opened: !prevState.opened }; });\r\n    }\r\n\r\n    handleSelectAll = event => {\r\n        let floatData = [...this.state.floatData];\r\n        const totalItems = floatData.length;\r\n        for (let i = 0; i < totalItems; i++) {\r\n            floatData[i] = { ...floatData[i], checked: event.target.checked };\r\n        }\r\n\r\n        this.props.onChange && this.props.onChange(getSelectedItems(floatData));\r\n        this.setState({ floatData });\r\n    }\r\n\r\n    handleSelect = (itemkey, isChecked) => {\r\n        let floatData = [...this.state.floatData];\r\n        const index = floatData.findIndex(item => item.key === itemkey);\r\n        floatData[index] = { ...floatData[index], checked: isChecked };\r\n\r\n        updateChild(floatData, itemkey, isChecked);\r\n        if (floatData[index].parentKey !== null && floatData[index].parentKey !== '') {\r\n            updateParent(floatData, floatData[index].parentKey, isChecked);\r\n        }\r\n\r\n        this.props.onChange && this.props.onChange(getSelectedItems(floatData));\r\n        this.setState({ floatData });\r\n    }\r\n\r\n    render() {\r\n        const { floatData, data } = this.state;\r\n        const selected = floatData.filter(item => item.checked);\r\n        const selectedText = getSelectedText(floatData);\r\n\r\n        return (\r\n            <div id={this.id} className=\"multiselect-treeview\" ref={element => this.wrapper = element}>\r\n                <div className=\"multiselect-treeview-dropdown-button\" onClick={this.onToggle}>\r\n                    <span className=\"selected-text\">{selectedText}</span>\r\n                    <span className=\"up-down-icon\"><span className={this.state.opened ? 'up' : 'down'} /></span>\r\n                </div>\r\n                <div className={`multiselect-treeview-dropdown-list ${this.state.opened ? '' : 'hidden'}`}>\r\n                    <div className=\"multiselect-treeview-select-all\">\r\n                        <div className=\"checkbox-wrapper\">\r\n                            <input type=\"checkbox\" id=\"selectAll\"\r\n                                checked={floatData.length === selected.length}\r\n                                onChange={this.handleSelectAll}\r\n                            />\r\n                            <label htmlFor=\"selectAll\"> Select all</label>\r\n                        </div>\r\n                    </div>\r\n                    <div className=\"multiselect-treeview-items\">\r\n                        {\r\n                            data.map(item =>\r\n                                <ul key={item.key}>\r\n                                    <li className=\"multiselect-treeview-item\">\r\n                                        <TreeNode\r\n                                            data={item}\r\n                                            floatData={floatData}\r\n                                            onSelect={this.handleSelect}\r\n                                        />\r\n                                    </li>\r\n                                </ul>\r\n                            )\r\n                        }\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { PureComponent, Fragment } from 'react';\r\n\r\nexport default class TreeNode extends PureComponent {\r\n    handleChange = event => {\r\n        const itemkey = this.props.data.key;\r\n        this.props.onSelect(itemkey, event.target.checked);\r\n    }\r\n\r\n    render() {\r\n        const { data, floatData } = this.props;\r\n        const itemIndex = floatData.findIndex(item => item.key === data.key);\r\n\r\n        return (\r\n            <Fragment>\r\n                <div className=\"checkbox-wrapper\">\r\n                    <input type=\"checkbox\" id={data.key} checked={floatData[itemIndex].checked} onChange={this.handleChange} />\r\n                    <label htmlFor={data.key}> {data.text}</label>\r\n                </div>\r\n                {\r\n                    data.items && data.items.length > 0 &&\r\n                    <ul>\r\n                        {\r\n                            data.items.map(item =>\r\n                                <li key={item.key} className=\"multiselect-treeview-item is-child\">\r\n                                    <TreeNode\r\n                                        data={item}\r\n                                        floatData={floatData}\r\n                                        onSelect={this.props.onSelect}\r\n                                    />\r\n                                </li>\r\n                            )\r\n                        }\r\n                    </ul>\r\n                }\r\n            </Fragment>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\nimport moment from 'moment';\r\n\r\nimport { DateFormat } from '../constants';\r\n\r\nexport default class WeekPicker extends PureComponent {\r\n    componentDidMount() {\r\n        this.$el = $(this.el);\r\n        this.updateWeekPicker();\r\n\r\n        document.addEventListener('mousedown', this.handleClickOutside);\r\n    }\r\n\r\n    componentDidUpdate(prevProps) {\r\n        if (this.props.fromDate !== prevProps.fromDate || this.props.toDate !== prevProps.toDate) {\r\n            this.updateWeekPicker();\r\n        }\r\n    }\r\n\r\n    componentWillUnmount() {\r\n        this.$el.weekpicker('destroy');\r\n        document.removeEventListener('mousedown', this.handleClickOutside);\r\n    }\r\n\r\n    handleClickOutside = event => {\r\n        if (this.wrapperRef && !this.wrapperRef.contains(event.target)) {\r\n            this.$el.hide();\r\n        }\r\n    };\r\n\r\n    updateWeekPicker = () => {\r\n        const vm = this;\r\n\r\n        this.$el.weekpicker({\r\n            firstDay: 1,\r\n            onSelect: function (dateText, startDateText, startDate, endDate) {\r\n                vm.props.onChange(moment(startDate).format(DateFormat), moment(endDate).format(DateFormat));\r\n                vm.$el.hide();\r\n            }\r\n        });\r\n\r\n        this.$el.weekpicker('setDate', new Date(new Date(this.props.fromDate)));\r\n    };\r\n\r\n    handleShowCalendar = () => {\r\n        this.$el.toggle();\r\n    };\r\n\r\n    render() {\r\n        return (\r\n            <div className=\"weekpicker-wrapper\" ref={node => this.wrapperRef = node}>\r\n                <input\r\n                    value={this.props.fromDate}\r\n                    onClick={this.handleShowCalendar}\r\n                    className=\"fromDate form-control\" readOnly\r\n                />\r\n                <input value={this.props.toDate}\r\n                    onClick={this.handleShowCalendar}\r\n                    className=\"toDate form-control\" readOnly\r\n                />\r\n                <div className=\"calendar\" ref={node => this.el = node} />\r\n                <i className=\"icon-calendar fa fa-calendar\" onClick={this.handleShowCalendar} />\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\nimport { Dropdown, MenuItem } from 'react-bootstrap';\r\n\r\nexport default class ColorDescription extends PureComponent {\r\n    render() {\r\n        return (\r\n            <Dropdown id={`dropdownColorDescription`} componentClass=\"span\" className=\"dropdown-color\">\r\n                <Dropdown.Toggle noCaret className=\"btn\">\r\n                    <img src=\"../wwwroot/sources/styles/images/pantone.svg\" width=\"17\" />\r\n                </Dropdown.Toggle>\r\n                <Dropdown.Menu>\r\n                    <MenuItem><span className=\"holiday\" />Public Holiday</MenuItem>\r\n                    <MenuItem><span className=\"offday\" />Off Day</MenuItem>\r\n                    <MenuItem><span className=\"offdayreplacement\" />Off Replacement</MenuItem>\r\n                    <MenuItem><span className=\"keepinviewday\" />Keep In View</MenuItem>\r\n                    <MenuItem><span className=\"changeshift\" />Change Shift</MenuItem>\r\n                    <MenuItem><span className=\"overtime\" />Overtime</MenuItem>\r\n                    <MenuItem><span className=\"annualleave\" />Annual Leave</MenuItem>\r\n                    <MenuItem><span className=\"unpaidleave\" />Unpaid Leave</MenuItem>\r\n                    <MenuItem><span className=\"businesstrip\" />Business Trip</MenuItem>\r\n                    <MenuItem><span className=\"weddingleave\" />Wedding Leave</MenuItem>\r\n                    <MenuItem><span className=\"leavehalfday2\" />2 Leaves Half Day</MenuItem>\r\n                    <MenuItem><span className=\"leaveday\" />Others Leave</MenuItem>\r\n                </Dropdown.Menu>\r\n            </Dropdown>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\nimport { getTotalOffDays } from '../common.functions';\r\n\r\nexport default class ColIndex extends PureComponent {\r\n    render() {\r\n        const { data } = this.props;\r\n        const totalOffDaysDefault = data.offDaysbyWeek + data.totalOffDayReplacement,\r\n            totalOffDays = getTotalOffDays(data);\r\n\r\n        return (\r\n            <div className=\"table-cell cell-index\">\r\n                {totalOffDaysDefault < totalOffDays ? <i className=\"fa fa-exclamation-triangle\" /> : ''}\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\nimport { OverlayTrigger, Tooltip } from 'react-bootstrap';\r\n\r\nexport default class TooltipRequestInfo extends PureComponent {\r\n    render() {\r\n        return (\r\n            <OverlayTrigger trigger={['hover']} placement={'top'}\r\n                overlay={\r\n                    <Tooltip id={this.props.id}>\r\n                        {this.props.requestInfo.details}\r\n                    </Tooltip>\r\n                }\r\n            >\r\n                {\r\n                    this.props.isLeaveHalfDay\r\n                        ? <span className={`halfdaycode ${this.props.requestInfo.classOfLeave}`}>{this.props.requestInfo.leaveCode}</span>\r\n                        : <i className=\"fa fa-info-circle\" />\r\n                }\r\n            </OverlayTrigger>\r\n        );\r\n    }\r\n}","import 'jquery-ui-bundle/jquery-ui';\r\nimport '../../../jquery-weekpicker';\r\n\r\nimport React, { Component, Fragment } from 'react';\r\nimport ReactDOM from 'react-dom';\r\nimport axios from 'axios';\r\nimport moment from 'moment';\r\n\r\nimport { axiosError, blockUI, unblockUI, resolveClientUrl } from '../../../shared/common.functions';\r\nimport buildData from '../../../shared/components/react-tree-multiselect/buildData';\r\nimport { DateFormat } from '../../../shared/constants';\r\nimport Search from '../Search';\r\nimport Table from './table/table';\r\n\r\nexport default class App extends Component {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        const fromDate = moment().day('Monday').format(DateFormat),\r\n            toDate = moment(fromDate).add(6, 'days').format(DateFormat);\r\n\r\n        this.state = {\r\n            filter: {\r\n                fromDate: fromDate,\r\n                toDate: toDate,\r\n                teamIds: '',\r\n                employee: { value: 0, label: '' }\r\n            },\r\n            schedules: [],\r\n            employeeOptions: []\r\n        };\r\n\r\n        this.teamOptions = [];\r\n        this.currentWeek = { fromDate, toDate };\r\n        this.selectedWeek = { fromDate, toDate };\r\n    }\r\n\r\n    componentDidMount() {\r\n        axios(resolveClientUrl('Section/GetOrgChart'))\r\n            .then(response => {\r\n                this.teamOptions = response.data;\r\n                const { floatData } = buildData(response.data);\r\n                const filter = { ...this.state.filter, teamIds: floatData.filter(item => item.isLeaf).map(item => item.id).join(',') };\r\n\r\n                this.getWeeklyShedules(filter);\r\n\r\n                this.setState({ filter: filter });\r\n            }).catch(axiosError);\r\n    }\r\n\r\n    handleFilterChange = (name, value) => {\r\n        this.setState({ filter: { ...this.state.filter, [name]: value } });\r\n    };\r\n\r\n    getEmployees = query => {\r\n        axios(resolveClientUrl('ScheduleArrange/GetEmployees'), {\r\n            params: {\r\n                teamIds: this.state.filter.teamIds,\r\n                query: query,\r\n                isIFrame: true\r\n            }\r\n        }).then(response => {\r\n            const employeeOptions = response.data.map(item => {\r\n                return {\r\n                    id: item.employeeId,\r\n                    value: `${item.nickname} (${item.fullName})`\r\n                };\r\n            });\r\n\r\n            this.setState({ employeeOptions: employeeOptions });\r\n        }).catch(axiosError);\r\n    };\r\n\r\n    getWeeklyShedules = filter => {\r\n        const fromDate = moment(filter.fromDate).format(DateFormat);\r\n        const toDate = moment(filter.toDate).format(DateFormat);\r\n\r\n        blockUI();\r\n\r\n        axios(resolveClientUrl('ScheduleArrange/GetWeeklySchedule'), {\r\n            params: {\r\n                fromDate: fromDate,\r\n                toDate: toDate,\r\n                teamIds: filter.teamIds,\r\n                employeeId: filter.employee.value === 0 ? null : filter.employee.value,\r\n                isIFrame: true\r\n            }\r\n        }).then(response => {\r\n            this.selectedWeek = { fromDate, toDate };\r\n            const attrNames = ['mondaySchedule', 'tuesdaySchedule', 'wednesdaySchedule',\r\n                'thursdaySchedule', 'fridaySchedule', 'saturdaySchedule', 'sundaySchedule'];\r\n            const schedules = response.data.schedules.map(team => {\r\n                team.members.map(schedule => {\r\n                    schedule.totalOffDayReplacement = 0;\r\n                    attrNames.forEach(attrName => {\r\n                        if (schedule[attrName].isOffDayReplacement) {\r\n                            schedule.totalOffDayReplacement = schedule.totalOffDayReplacement + 1;\r\n                        }\r\n                    });\r\n\r\n                    return schedule;\r\n                });\r\n\r\n                return team;\r\n            });\r\n\r\n            this.setState({\r\n                filter: { ...this.state.filter, fromDate, toDate },\r\n                schedules: schedules\r\n            });\r\n        }).catch(axiosError).then(() => unblockUI());\r\n    };\r\n\r\n    handleGetWeeklyShedules = isCurrentWeek => {\r\n        const filter = isCurrentWeek\r\n            ? { ...this.state.filter, fromDate: this.currentWeek.fromDate, toDate: this.currentWeek.toDate }\r\n            : this.state.filter;\r\n        this.setState({ filter });\r\n        this.getWeeklyShedules(filter);\r\n    };\r\n\r\n    handleGetPreviousWeekSchedule = () => {\r\n        const fromDate = moment(this.selectedWeek.fromDate).add(-7, 'days').format(DateFormat);\r\n        const toDate = moment(this.selectedWeek.toDate).add(-7, 'days').format(DateFormat);\r\n        const filter = { ...this.state.filter, fromDate, toDate };\r\n        this.setState({ filter });\r\n        this.getWeeklyShedules(filter);\r\n    };\r\n\r\n    handleGetNextWeekSchedule = () => {\r\n        const fromDate = moment(this.selectedWeek.fromDate).add(7, 'days').format(DateFormat);\r\n        const toDate = moment(this.selectedWeek.toDate).add(7, 'days').format(DateFormat);\r\n        const filter = { ...this.state.filter, fromDate, toDate };\r\n        this.setState({ filter });\r\n        this.getWeeklyShedules(filter);\r\n    };\r\n\r\n    render() {\r\n        const { schedules } = this.state;\r\n\r\n        return (\r\n            <Fragment>\r\n                <Search\r\n                    showExportExcel={false}\r\n                    teamOptions={this.teamOptions}\r\n                    employeeOptions={this.state.employeeOptions}\r\n                    filter={this.state.filter}\r\n                    onSearchEmployees={this.getEmployees}\r\n                    onChange={this.handleFilterChange}\r\n                    onSubmit={this.handleGetWeeklyShedules}\r\n                />\r\n                <Table\r\n                    fromDate={this.selectedWeek.fromDate} toDate={this.selectedWeek.toDate}\r\n                    data={schedules}\r\n                    onPrevious={this.handleGetPreviousWeekSchedule}\r\n                    onNext={this.handleGetNextWeekSchedule}\r\n                />\r\n            </Fragment>\r\n        );\r\n    }\r\n}\r\n\r\nReactDOM.render(<App />, document.getElementById('schedule-wrapper'));","import React, { PureComponent, Fragment } from 'react';\r\n\r\nimport THead from './THead';\r\nimport Row from './Row';\r\n\r\nexport default class Table extends PureComponent {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            isFixedHeader: false\r\n        };\r\n\r\n        this.contentScrollElement = document.getElementsByClassName('content_scroll')[0];\r\n    }\r\n\r\n    componentDidMount() {\r\n        this.contentScrollElement.addEventListener('scroll', this.handleScroll);\r\n    }\r\n\r\n    componentWillUnmount() {\r\n        this.contentScrollElement.removeEventListener('scroll', this.handleScroll);\r\n    }\r\n\r\n    handleScroll = event => {\r\n        const scrollTop = event.srcElement.scrollTop;\r\n        if (scrollTop > 100) {\r\n            if (!this.state.isFixedHeader) {\r\n                this.setState({ isFixedHeader: true });\r\n            }\r\n        } else {\r\n            if (this.state.isFixedHeader) {\r\n                this.setState({ isFixedHeader: false });\r\n            }\r\n        }\r\n    };\r\n\r\n    render() {\r\n        const { fromDate, toDate, data } = this.props;\r\n\r\n        return (\r\n            <div className=\"table-wrapper\">\r\n                <div className={`table-header ${this.state.isFixedHeader ? 'fixed' : ''}`}>\r\n                    <THead fromDate={fromDate} toDate={toDate}\r\n                        onPrevious={this.props.onPrevious}\r\n                        onNext={this.props.onNext}\r\n                    />\r\n                </div>\r\n                <div className=\"table-body\">\r\n                    {\r\n                        data.length === 0 &&\r\n                        <div className=\"nodata\">No information available</div>\r\n                    }\r\n                    {\r\n                        data.length > 0 &&\r\n                        data.map(team =>\r\n                            <Fragment key={team.teamId}>\r\n                                <div className=\"row-team\"><div className=\"team-name\">{team.name}</div></div>\r\n                                {\r\n                                    team.members.map((member, index) => <Row key={`row${index}`} data={member} />)\r\n                                }\r\n                            </Fragment>\r\n                        )\r\n                    }\r\n                </div>\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { PureComponent, Fragment } from 'react';\r\nimport moment from 'moment';\r\n\r\nimport ColorDescription from '../../table/ColorDescription';\r\n\r\nexport default class THead extends PureComponent {\r\n    dayOfWeeks = [0, 1, 2, 3, 4, 5, 6];\r\n\r\n    render() {\r\n        const { fromDate, toDate } = this.props;\r\n\r\n        return (\r\n            <Fragment>\r\n                <div className=\"header-control\">\r\n                    <div />\r\n                    <div>\r\n                        <button className=\"btn prev-week fa fa-chevron-left\" onClick={this.props.onPrevious} />\r\n                        <button className=\"btn next-week fa fa-chevron-right\" onClick={this.props.onNext} />\r\n                        <span className=\"label-week\">{`${fromDate} - ${toDate}`}</span>\r\n                        <ColorDescription />\r\n                    </div>\r\n                </div>\r\n                <div className=\"header\">\r\n                    <div className=\"table-cell cell-index\" />\r\n                    <div className=\"table-cell cell-nickname\">\r\n                        Nickname\r\n                    </div>\r\n                    {\r\n                        this.dayOfWeeks.map(item => {\r\n                            return (\r\n                                <div className=\"table-cell cell-shift\" key={`dayOfWeeks${item}`}>\r\n                                    {moment(fromDate).add(item, 'days').format('D MMM, ddd')}\r\n                                </div>\r\n                            );\r\n                        })\r\n                    }\r\n                </div>\r\n            </Fragment>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\n\r\nimport ColIndex from '../../table/ColIndex';\r\nimport ColNickname from './ColNickname';\r\nimport ColShift from './ColShift';\r\n\r\nexport default class Row extends PureComponent {\r\n    render() {\r\n        const { data } = this.props;\r\n\r\n        return (\r\n            <div className=\"table-row\">\r\n                <ColIndex data={data} />\r\n                <ColNickname employeeId={data.employeeId} nickname={data.nickname} remark={data.remark} />\r\n                <ColShift isUsedWeeklyDefaultShift={data.isUsedWeeklyDefaultShift}\r\n                    employeeId={data.employeeId} defaultShift={data.defaultShift} data={data.mondaySchedule}\r\n                    scheduleAttrName={'mondaySchedule'}\r\n                />\r\n                <ColShift isUsedWeeklyDefaultShift={data.isUsedWeeklyDefaultShift}\r\n                    employeeId={data.employeeId} defaultShift={data.defaultShift} data={data.tuesdaySchedule}\r\n                    scheduleAttrName={'tuesdaySchedule'}\r\n                />\r\n                <ColShift isUsedWeeklyDefaultShift={data.isUsedWeeklyDefaultShift}\r\n                    employeeId={data.employeeId} defaultShift={data.defaultShift} data={data.wednesdaySchedule}\r\n                    scheduleAttrName={'wednesdaySchedule'}\r\n                />\r\n                <ColShift isUsedWeeklyDefaultShift={data.isUsedWeeklyDefaultShift}\r\n                    employeeId={data.employeeId} defaultShift={data.defaultShift} data={data.thursdaySchedule}\r\n                    scheduleAttrName={'thursdaySchedule'}\r\n                />\r\n                <ColShift isUsedWeeklyDefaultShift={data.isUsedWeeklyDefaultShift}\r\n                    employeeId={data.employeeId} defaultShift={data.defaultShift} data={data.fridaySchedule}\r\n                    scheduleAttrName={'fridaySchedule'}\r\n                />\r\n                <ColShift isUsedWeeklyDefaultShift={data.isUsedWeeklyDefaultShift}\r\n                    employeeId={data.employeeId} defaultShift={data.defaultShift} data={data.saturdaySchedule}\r\n                    scheduleAttrName={'saturdaySchedule'}\r\n                />\r\n                <ColShift isUsedWeeklyDefaultShift={data.isUsedWeeklyDefaultShift}\r\n                    employeeId={data.employeeId} defaultShift={data.defaultShift} data={data.sundaySchedule}\r\n                    scheduleAttrName={'sundaySchedule'}\r\n                />\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\nimport { OverlayTrigger, Tooltip } from 'react-bootstrap';\r\n\r\nexport default class ColNickname extends PureComponent {\r\n    render() {\r\n        const { employeeId, nickname, remark } = this.props;\r\n\r\n        return (\r\n            <div className=\"table-cell cell-nickname\">\r\n                <div className=\"cell-nickname-wrapper\">\r\n                    <div className=\"info\">\r\n                        <div className=\"nickname\">{nickname}</div>\r\n                        <div className=\"remark-wrapper\">\r\n                            <i className={`icon-remark ${remark !== null && remark.length > 0 ? 'has-remark' : ''} fa fa-commenting-o`}\r\n                                title=\"Remark\"\r\n                            />\r\n                            <OverlayTrigger trigger={['hover']} placement={'top'}\r\n                                overlay={<Tooltip id={`remark${employeeId}`}>{remark}</Tooltip>}\r\n                            >\r\n                                <span className=\"remark\">{remark}</span>\r\n                            </OverlayTrigger>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\n\r\nimport { getColumnShiftInfo } from '../../common.functions';\r\nimport ShiftAutocomplete from '../../ShiftAutocomplete';\r\nimport TooltipRequestInfo from '../../table/TooltipRequestInfo';\r\n\r\nexport default class ColShift extends PureComponent {\r\n    render() {\r\n        const { employeeId, data, scheduleAttrName, defaultShift, isUsedWeeklyDefaultShift } = this.props;\r\n        const shiftInfo = getColumnShiftInfo(data, false, defaultShift, isUsedWeeklyDefaultShift);\r\n\r\n        let shift;\r\n        if (data.shift === null) {\r\n            shift = { code: shiftInfo.value, name: shiftInfo.value };\r\n        } else if (data.shift.code !== shiftInfo.value) {\r\n            shift = { ...data.shift, code: shiftInfo.value, name: shiftInfo.value };\r\n        } else {\r\n            shift = data.shift;\r\n        }\r\n\r\n        return (\r\n            <div className=\"table-cell cell-shift\">\r\n                <div className={`cell-shift-wrapper ${data.isLeaveHalfDay ? 'leavehalfday' : ''}`}>\r\n                    {\r\n                        shiftInfo.details !== '' &&\r\n                        <TooltipRequestInfo id={`moreInfo-${scheduleAttrName}${employeeId}`}\r\n                            requestInfo={shiftInfo}\r\n                            isLeaveHalfDay={data.isLeaveHalfDay}\r\n                        />\r\n                    }\r\n                    <ShiftAutocomplete shift={shift} className={shiftInfo.class} isDisabled />\r\n                </div>\r\n            </div>\r\n        );\r\n    }\r\n}"],"sourceRoot":""}
